def top_k_frequent(items, k):
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    ordered = sorted(counts, key=lambda word: (-counts[word], word))
    if not ordered:
        raise ValueError("items must not be empty")
    if k <= 0:
        return []
    return ordered[:k]
